/* eslint-disable */
/**
 * LevelData.ts · 30 关关卡数据（**自动生成，请勿手工编辑**）
 *
 * 来源：docs-verify/game-5/game-play/levels.json（v7 口径 · 38/38 验收 · 满清可解 30/30）
 *   ★ 第 62 轮：牌面组已由"全是碰"改为「碰 70% + 吃 30%」—— 见 f 字段与 so 的说明
 * 生成：python3 tools/gen-level-data.py
 *
 * 编码口径（为压体积，全部走整数扁平数组）：
 *   t: 每 4 个一组 = [x*wu*1000, y*wu*1000, 层号 z, rot 0=竖/1=横(90°)]
 *   f: 每张一个 = suit*10 + num（wan=0 / tiao=1 / tong=2）
 *   so: 清序（生成器 `greedy_peel` 的输出）—— 每 3 张连续位构成**一个合法可消组**
 *        （碰＝三张同牌面；吃＝同一花色里点数连着三张。判定口径见 core/MatchRule.ts）
 *   x,y 是 **wu 单位**（牌宽倍数，原点 = 安全区中心），乘 1000 取整，精度 0.001 wu
 */

export interface LevelSeg {
    /** 该段最低层号（含） */
    lo: number;
    /** 该段最高层号（不含） —— 段序自顶向下 */
    hi: number;
    /** 段内张数（恒为 3 的倍数） */
    n: number;
}

export interface LevelDef {
    /** 关卡号 1~30 */
    lv: number;
    /** 整关张数（3 的倍数） */
    n: number;
    /** 单堆层数 */
    layers: number;
    /** 单关唯一牌宽（设计 px @750） */
    w: number;
    /** 单关唯一牌高 = round(w * 4/3) */
    h: number;
    /** 分段（转场波次，自顶向下） */
    segs: LevelSeg[];
    /** 扁平牌位：[x1000, y1000, z, rot90] × n */
    t: number[];
    /** 扁平牌面：suit*10 + num × n */
    f: number[];
    /**
     * ★ 第 46 轮：**清序** —— 生成器 `greedy_peel()` 的输出，是 0..n-1 的一个排列。
     *
     * 【语义】`so[k]` = "顺手的打法"里第 k 个被消掉的牌下标。
     * 【不变量】每连续 3 位 `so[3k..3k+2]` 构成**一个合法可消组** ——
     *   「碰」（三张同牌面）或「吃」（同花色里点数连着三张，不跨花色）。
     *   第 62 轮起不再"全是碰"：生成器按用户拍板把约 30% 的组填成「吃」
     *   （比例沿关卡号渐进：L1~2 纯碰 → L3 起爬升 → L10 起保持 30%）。
     * 【用途】**难度置换**（`core/Difficulty.ts`）按它给每张牌算名次：难度参数把名次
     *   切成连续块、只在块内洗牌面 ⇒ 打散"顺手就是一组"的结构。
     * ⚠️ 它**不是唯一解**，也不参与可点判定；只用来定位"哪三张是一组"。
     */
    so: number[];
}

